import React from "react";

const Stall = () => {
    return (
        <div className="min-h-screen bg-slate-900 flex items-center justify-center overflow-hidden perspective-1000">
            {/* 3D Wrapper */}
            <div
                className="relative transform-gpu transition-transform duration-700 hover:rotate-y-12"
                style={{ transformStyle: 'preserve-3d', transform: 'rotateX(15deg) rotateY(-20deg)' }}
            >

                {/* Floor/Base */}
                <div className="w-96 h-96 bg-slate-700 rounded-sm shadow-2xl"
                    style={{ transform: 'rotateX(90deg) translateZ(-180px)', opacity: 0.5 }}>
                </div>

                {/* Back Wall */}
                <div className="absolute top-0 w-96 h-80 bg-gradient-to-br from-blue-600 to-indigo-800 border-4 border-blue-400 flex flex-col items-center justify-center text-white shadow-xl">
                    <h2 className="text-4xl font-black tracking-tighter">VANTAGE</h2>
                    <p className="text-xs uppercase tracking-widest opacity-80">Premium Exhibits</p>

                    {/* Decorative Screen on Wall */}
                    <div className="mt-8 w-64 h-32 bg-slate-900 rounded border border-blue-300 flex items-center justify-center overflow-hidden">
                        <div className="w-full h-full bg-blue-500/20 animate-pulse flex items-center justify-center text-[10px] text-blue-300">
                            LIVE STREAMING...
                        </div>
                    </div>
                </div>

                {/* Side Wall (Left) */}
                <div className="absolute top-0 w-40 h-80 bg-blue-900 border-l-4 border-blue-400 origin-left"
                    style={{ transform: 'rotateY(90deg)' }}>
                </div>

                {/* Front Counter Desk */}
                <div
                    className="absolute top-48 left-16 w-64 h-32 bg-white shadow-2xl flex items-center justify-center border-b-8 border-gray-300"
                    style={{ transform: 'translateZ(120px)' }}
                >
                    <div className="text-center">
                        <div className="text-blue-600 font-bold text-lg italic">RECEPTION</div>
                        <div className="w-12 h-1 bg-blue-600 mx-auto mt-1"></div>
                    </div>

                    {/* Counter Top */}
                    <div className="absolute -top-4 w-full h-4 bg-gray-100 origin-bottom"
                        style={{ transform: 'rotateX(-90deg)' }}>
                    </div>
                </div>

                {/* Floating Interactive Product (The "3D" Pop) */}
                <div
                    className="absolute -top-10 left-10 w-24 h-24 bg-yellow-400 rounded-full flex items-center justify-center shadow-lg animate-bounce cursor-pointer group"
                    style={{ transform: 'translateZ(200px)' }}
                >
                    <span className="text-3xl group-hover:scale-125 transition">🎁</span>
                    <div className="absolute -bottom-10 bg-white text-black text-[10px] px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition whitespace-nowrap font-bold">
                        CLICK FOR BROCHURE
                    </div>
                </div>

            </div>

            {/* UI Overlay */}
            <div className="absolute bottom-10 left-10 text-white">
                <h1 className="text-2xl font-bold">Virtual Stall #A-01</h1>
                <p className="text-blue-400">Move your mouse to tilt view</p>
            </div>

            <button
                onClick={() => window.history.back()}
                className="absolute top-10 left-10 text-white border border-white/30 px-4 py-2 rounded-full hover:bg-white hover:text-black transition"
            >
                ← Exit Stall
            </button>
        </div>
    );
};

export default Stall;
